if (from.body && to.socket) {
    // vc patch: client stop aborts node-fetch, which emits AbortError on the body.
    // stream.pipe drops its own error listener and re-emits; with no other listener that
    // becomes an uncaught exception and server-main exits. Keep one listener for the life of the body.
    // Only a client stop returns quietly. Other errors log name and code, then destroy the response.
    from.body.on('error', (error) => {
        const aborted = error?.name === 'AbortError' || error?.type === 'aborted';
        if (aborted) return;
        console.warn(`Streaming request stream error: name=${error?.name || 'Error'} code=${error?.code || ''}`);
        try {
            to.destroy(error);
        } catch { /* response already closed */ }
    });
    from.body.pipe(to);

    to.socket.on('close', function () {
        try {
            if (from.body instanceof Readable) from.body.destroy(); // Close the remote stream
        } catch { /* client already gone */ }

        try {
            to.end(); // End the Express response
        } catch { /* response already finished */ }
    });
